setup:
cat > src/math.ts <<'EOF'
export function double(n: number): number {
	return n * 2;
}

export function triple(n: number): number {
	return n * 3;
}
EOF

cat > src/index.ts <<'EOF'
export { double, triple } from "./math.ts";
EOF

cat > test/api.test.ts <<'EOF'
import assert from "node:assert/strict";
import { test } from "node:test";
import { double, triple } from "../src/index.ts";

test("public API doubles and triples", () => {
	assert.equal(double(4), 8);
	assert.equal(triple(4), 12);
});
EOF
